const { html } = await pdf.html("demo/report.pdf");
const page = new DOMParser().parseFromString(html, "text/html");
const number = (text) => Number(text.replace(/[^0-9.-]/g, ""));
const rows = [...page.querySelector("table").querySelectorAll("tr")].slice(1)
  .map((tr) => [...tr.querySelectorAll("td, th")].map((cell) => cell.textContent.trim()));
const report = Object.fromEntries(rows.filter(([region]) => region !== "Total").map(([region, sales]) => [region, number(sales)]));
const reportTotal = number(rows.find(([region]) => region === "Total")[1]);

const data = await sql("SELECT region, sum(amount) AS sales FROM read_xlsx('demo/sales.xlsx') GROUP BY region");
const dataTotal = d3.sum(data, (d) => d.sales);
const differences = data.filter((d) => report[d.region] !== d.sales)
  .map((d) => `${d.region}: report ${report[d.region]}, data ${d.sales}`);
const hidden = [...page.querySelectorAll("[data-hidden]")].map((element) => element.getAttribute("data-hidden"));
return `${differences.join("; ") || "no differences"}; report total ${reportTotal}, data total ${dataTotal}; hidden elements: ${hidden.length} (${hidden.join(", ")})`;
